	"BRT_WEIGHT_OF_KOR" NUMBER
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_ARTICUL_REPLENISH_RULE" 
   (	"ARTICUL_REPLENISH_RULE_ID" NUMBER NOT NULL ENABLE, 
	"ARTICUL" VARCHAR2(80) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REPLENISHMENT_METHOD" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'MINIMAX' NOT NULL ENABLE, 
	"REPLENISHMENT_RELEASE_POLICY" VARCHAR2(40) COLLATE "USING_NLS_COMP" DEFAULT 'LAYER_TRIGGER' NOT NULL ENABLE, 
	"REPLENISHMENT_QTY_MODE" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'FILL_TO_VOLUME' NOT NULL ENABLE, 
	"MIN_TRIGGER_BOX_QTY" NUMBER, 
	"MIN_TRIGGER_LAYER_QTY" NUMBER DEFAULT 1, 
	"SAFETY_LAYER_QTY" NUMBER, 
	"BOXES_PER_LAYER" NUMBER, 
	"BOXES_PER_PALLET" NUMBER, 
	"BOX_VOLUME_M3" NUMBER, 
	"ALLOW_PARTIAL_PALLET" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"PREDICTIVE_BUFFER_MIN" NUMBER, 
	"PICK_RATE_SOURCE" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'MIXED' NOT NULL ENABLE, 
	"RECHECK_ON_PICK_EVENT" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"ACTIVE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"COMMENT_TEXT" VARCHAR2(500) COLLATE "USING_NLS_COMP", 
	"CREATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"UPDATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"UPDATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_ART_REPL_RULE_CHK1" CHECK (REPLENISHMENT_METHOD in ('IMMEDIATE', 'MINIMAX')) ENABLE, 
	 CONSTRAINT "RRL_ART_REPL_RULE_CHK2" CHECK (REPLENISHMENT_RELEASE_POLICY in ('LAYER_TRIGGER', 'PREDICTIVE_LEAD_TIME')) ENABLE, 
	 CONSTRAINT "RRL_ART_REPL_RULE_CHK3" CHECK (REPLENISHMENT_QTY_MODE in ('FULL_PALLET', 'HALF_PALLET', 'FILL_TO_VOLUME')) ENABLE, 
	 CONSTRAINT "RRL_ART_REPL_RULE_CHK4" CHECK (ALLOW_PARTIAL_PALLET in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_ART_REPL_RULE_CHK5" CHECK (PICK_RATE_SOURCE in ('PLAN', 'FACT', 'MIXED')) ENABLE, 
	 CONSTRAINT "RRL_ART_REPL_RULE_CHK6" CHECK (RECHECK_ON_PICK_EVENT in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_ART_REPL_RULE_CHK7" CHECK (ACTIVE in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_ART_REPL_RULE_PK" PRIMARY KEY ("ARTICUL_REPLENISH_RULE_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_ART_REPL_RULE_U1" UNIQUE ("ARTICUL")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


