  CREATE TABLE "RABAEV"."RRL_BOM" 
   (	"BOM_ID" NUMBER NOT NULL ENABLE, 
	"BOM_CODE" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BOM_NAME" VARCHAR2(255) COLLATE "USING_NLS_COMP", 
	"TARGET_ARTICUL" VARCHAR2(40) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TARGET_MOD_ID" NUMBER, 
	"TARGET_GTIN" VARCHAR2(14) COLLATE "USING_NLS_COMP", 
	"BOM_KIND" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'FINISHED_GOODS' NOT NULL ENABLE, 
	"BASE_QTY" NUMBER NOT NULL ENABLE, 
	"BASE_UNIT_CODE" VARCHAR2(20) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"IS_PRIMARY" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE, 
	"STATUS" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'DRAFT' NOT NULL ENABLE, 
	"VALID_FROM" DATE NOT NULL ENABLE, 
	"VALID_TO" DATE, 
	"WARE_ID" NUMBER, 
	"PRODUCTION_LINE" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"VERSION_NO" NUMBER DEFAULT 1 NOT NULL ENABLE, 
	"PARENT_BOM_ID" NUMBER, 
	"COMMENT_TEXT" VARCHAR2(1000) COLLATE "USING_NLS_COMP", 
	"CREATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"UPDATED_AT" DATE, 
	"UPDATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"APPROVED_AT" DATE, 
	"APPROVED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_BOM_CHK1" CHECK (BOM_KIND in ('FINISHED_GOODS', 'SEMIFINISHED')) ENABLE, 
	 CONSTRAINT "RRL_BOM_CHK2" CHECK (BASE_QTY > 0) ENABLE, 
	 CONSTRAINT "RRL_BOM_CHK3" CHECK (IS_PRIMARY in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_BOM_CHK4" CHECK (STATUS in ('DRAFT', 'APPROVED', 'ACTIVE', 'BLOCKED', 'ARCHIVED')) ENABLE, 
	 CONSTRAINT "RRL_BOM_CHK5" CHECK (VALID_TO is null or VALID_TO >= VALID_FROM) ENABLE, 
	 CONSTRAINT "RRL_BOM_PK" PRIMARY KEY ("BOM_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_BOM_U1" UNIQUE ("BOM_CODE")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_BOM_AUDIT" 
   (	"BOM_AUDIT_ID" NUMBER NOT NULL ENABLE, 
	"BOM_ID" NUMBER, 
