	"COMPONENT_MOD_ID" NUMBER, 
	"COMPONENT_NAME" VARCHAR2(255) COLLATE "USING_NLS_COMP", 
	"QTY_PER_BASE" NUMBER, 
	"UNIT_CODE" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"LOSS_PERCENT" NUMBER DEFAULT 0 NOT NULL ENABLE, 
