	"MAX_TOLERANCE_PCT" NUMBER, 
	"IS_REQUIRED" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"SUBSTITUTION_GROUP" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"REPLACEMENT_RATIO" NUMBER, 
	"COMMENT_TEXT" VARCHAR2(1000) COLLATE "USING_NLS_COMP", 
	"CREATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
