	"UPDATED_AT" DATE, 
	"UPDATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_BOM_LINE_CHK1" CHECK (COMPONENT_TYPE in ('RAW', 'SEMIFINISHED', 'PACKAGING', 'ADDITIVE', 'SERVICE')) ENABLE, 
	 CONSTRAINT "RRL_BOM_LINE_CHK2" CHECK (QTY_PER_BASE is null or QTY_PER_BASE > 0) ENABLE, 
	 CONSTRAINT "RRL_BOM_LINE_CHK3" CHECK (IS_REQUIRED in (0, 1)) ENABLE, 
