	"PICK_FACE_ID" NUMBER, 
	"PICK_ROUTE_CELL_ID" NUMBER, 
	"PICK_SEQUENCE" NUMBER, 
	"PLANNED_QTY" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"PICKED_QTY" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"STATUS" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'NEW' NOT NULL ENABLE, 
	"REQUIRED_SCAN_MODE" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"LAST_OFFLINE_EVENT_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"CREATED_AT" TIMESTAMP (6) DEFAULT systimestamp NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"STARTED_AT" TIMESTAMP (6), 
	"DONE_AT" TIMESTAMP (6), 
	"UPDATED_AT" TIMESTAMP (6), 
	"UPDATED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"STACK_STAGE" VARCHAR2(10) COLLATE "USING_NLS_COMP" DEFAULT 'MAIN' NOT NULL ENABLE, 
	"STACK_POLICY_VERSION" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	 CONSTRAINT "RRL_CASE_PICK_LINE_CHK1" CHECK (STATUS in ('NEW', 'ACTIVE', 'SKIPPED', 'WAIT_REPLENISHMENT', 'PARTIAL', 'PICKED', 'SHORT_PICKED', 'SYNC_CONFLICT', 'CANCELLED', 'FAILED')) ENABLE, 
	 CONSTRAINT "RRL_CASE_PICK_LINE_PK" PRIMARY KEY ("CASE_PICK_LINE_ID")
  USING INDEX  ENABLE, 
