  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_CASE_STACK_STAGE_CK" CHECK (STACK_STAGE in('BASE','MAIN','TOP')and STACK_POLICY_VERSION>=0) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_CASE_PICK_SETTING" 
   (	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"SCAN_CELL_REQUIRED" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"SCAN_PRODUCT_REQUIRED" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"SCAN_BOX_REQUIRED" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE, 
	"SCAN_CONTAINER_REQUIRED" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"QTY_CONFIRM_MODE" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'ALWAYS' NOT NULL ENABLE, 
	"SHORTAGE_BEHAVIOR" VARCHAR2(40) COLLATE "USING_NLS_COMP" DEFAULT 'WAIT_REPLENISHMENT' NOT NULL ENABLE, 
	"ALLOW_MANUAL_ORDER_CHANGE" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE, 
	"PALLET_COMPLETE_STAGE" VARCHAR2(40) COLLATE "USING_NLS_COMP" DEFAULT 'AFTER_CONTROL' NOT NULL ENABLE, 
	"CONTROL_MODE" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'WEIGHT_OR_AUDIT' NOT NULL ENABLE, 
	"LABEL_PRINT_STAGE" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'AFTER_PICKING' NOT NULL ENABLE, 
	"AUTO_INVENTORY_ON_SHORT" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"INVENTORY_ASSIGNMENT_MODE" VARCHAR2(40) COLLATE "USING_NLS_COMP" DEFAULT 'RESOURCE_ROLE' NOT NULL ENABLE, 
	"INVENTORY_RESOURCE_TYPE" VARCHAR2(40) COLLATE "USING_NLS_COMP" DEFAULT 'INVENTORY' NOT NULL ENABLE, 
	"OFFLINE_ENABLED" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"OFFLINE_SCOPE" VARCHAR2(40) COLLATE "USING_NLS_COMP" DEFAULT 'ISSUED_TASKS_ONLY' NOT NULL ENABLE, 
	"ACTIVE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CREATED_AT" TIMESTAMP (6) DEFAULT systimestamp NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"UPDATED_AT" TIMESTAMP (6), 
	"UPDATED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"SHORT_CONFIRM_MODE" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'AUDITOR' NOT NULL ENABLE, 
	"SHORT_RECOVERY_SLA_SECONDS" NUMBER DEFAULT 300 NOT NULL ENABLE, 
	 CONSTRAINT "RRL_CASE_PICK_SETTING_CHK1" CHECK (QTY_CONFIRM_MODE in ('ALWAYS', 'ONLY_DEVIATION', 'SCAN_INCREMENT')) ENABLE, 
	 CONSTRAINT "RRL_CASE_PICK_SETTING_CHK2" CHECK (SHORTAGE_BEHAVIOR in ('WAIT_REPLENISHMENT', 'SKIP_AND_RETURN', 'PARTIAL_PICK', 'CLOSE_SHORT', 'CALL_REACHTRUCK')) ENABLE, 
	 CONSTRAINT "RRL_CASE_PICK_SETTING_CHK3" CHECK (PALLET_COMPLETE_STAGE in ('LINES_PICKED', 'PICKER_CLOSED', 'CONSOLIDATION', 'AFTER_CONTROL')) ENABLE, 
	 CONSTRAINT "RRL_CASE_PICK_SETTING_CHK4" CHECK (CONTROL_MODE in ('NONE', 'AUDIT', 'WEIGHT', 'WEIGHT_OR_AUDIT')) ENABLE, 
	 CONSTRAINT "RRL_CASE_PICK_SETTING_CHK5" CHECK (LABEL_PRINT_STAGE in ('AFTER_PICKING', 'AFTER_CONTROL', 'MANUAL')) ENABLE, 
	 CONSTRAINT "RRL_CASE_PICK_SETTING_CHK6" CHECK (SCAN_CELL_REQUIRED in (0, 1) and SCAN_PRODUCT_REQUIRED in (0, 1) and SCAN_BOX_REQUIRED in (0, 1) and SCAN_CONTAINER_REQUIRED in (0, 1) and ALLOW_MANUAL_ORDER_CHANGE in (0, 1) and AUTO_INVENTORY_ON_SHORT in (0, 1) and OFFLINE_ENABLED in (0, 1) and ACTIVE in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_CASE_PICK_SETTING_PK" PRIMARY KEY ("WARE_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_SHORT_RECOVERY_SETTING_CK" CHECK (SHORT_CONFIRM_MODE in('SELF','AUDITOR') and SHORT_RECOVERY_SLA_SECONDS between 1 and 300 and SHORT_RECOVERY_SLA_SECONDS=trunc(SHORT_RECOVERY_SLA_SECONDS)) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


