	"INVESTIGATION_VERSION" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"INVESTIGATION_STATUS" VARCHAR2(12) COLLATE "USING_NLS_COMP" DEFAULT 'OPEN' NOT NULL ENABLE, 
	"CREATED_AT_INSTANT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp, 
	"WEIGHT_POLICY_VERSION" NUMBER, 
	"WEIGHT_TOLERANCE_PCT" NUMBER(5,2), 
	"WEIGHT_ORDER_REQUESTED_KG" NUMBER(27,9), 
	"WEIGHT_ORDER_PICKED_KG" NUMBER(27,9), 
	"WEIGHT_DECISION_OPERATION" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_CASE_PICK_SHORT_CHK1" CHECK (STATUS in ('CREATED', 'PENDING_APPROVAL', 'ACCEPTED', 'REJECTED', 'CANCELLED', 'SHORT_CLOSED')) ENABLE, 
	 CONSTRAINT "RRL_CASE_PICK_SHORT_PK" PRIMARY KEY ("CASE_PICK_SHORT_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_SHORT_RECOVERY_STATE_CK" CHECK (RECOVERY_STATE in('WAIT_INVENTORY','WAIT_REPLENISHMENT','READY','RESUMED','FAILED')) ENABLE, 
	 CONSTRAINT "RRL_SHORT_INV_STATUS_C" CHECK (INVESTIGATION_STATUS in('OPEN','REVIEWING','CLOSED')) ENABLE, 
	 CONSTRAINT "RRL_CASE_WT_DECISION_CK" CHECK (
 (WEIGHT_DECISION_OPERATION is null and WEIGHT_POLICY_VERSION is null and WEIGHT_TOLERANCE_PCT is null and WEIGHT_ORDER_REQUESTED_KG is null and WEIGHT_ORDER_PICKED_KG is null)
 or(WEIGHT_DECISION_OPERATION is not null and WEIGHT_POLICY_VERSION is not null and WEIGHT_POLICY_VERSION>=0
 and WEIGHT_TOLERANCE_PCT is not null and WEIGHT_TOLERANCE_PCT between 0 and 100
 and WEIGHT_ORDER_REQUESTED_KG is not null and WEIGHT_ORDER_REQUESTED_KG>0 and WEIGHT_ORDER_PICKED_KG is not null and WEIGHT_ORDER_PICKED_KG>0)) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


