	"INN" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"KPP" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"GLN" VARCHAR2(32) COLLATE "USING_NLS_COMP", 
	"EDI_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"DEFAULT_VEHICLE_TYPE_ID" NUMBER, 
