	"DEFAULT_MIN_SHELF_LIFE_DAYS" NUMBER, 
	"DEFAULT_MIN_SHELF_LIFE_PERCENT" NUMBER, 
	"ACTIVE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CREATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"UPDATED_AT" DATE, 
	"UPDATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_CUSTOMER_CHK1" CHECK (CUSTOMER_TYPE in ('STORE', 'CHAIN', 'DISTRIBUTOR', 'LEGAL_ENTITY', 'OTHER')) ENABLE, 
