	 CONSTRAINT "RRL_CUSTOMER_CHK3" CHECK (SPLIT_ORDER_BY_VEHICLE_CAPACITY in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_CUSTOMER_CHK4" CHECK (DEFAULT_MIN_SHELF_LIFE_PERCENT is null or (DEFAULT_MIN_SHELF_LIFE_PERCENT >= 0 and DEFAULT_MIN_SHELF_LIFE_PERCENT <= 100)) ENABLE, 
	 CONSTRAINT "RRL_CUSTOMER_PK" PRIMARY KEY ("CUSTOMER_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_CUSTOMER_U1" UNIQUE ("CUSTOMER_CODE")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


