	 CHECK (CANONICAL_REQUEST is json) ENABLE, 
	 CHECK (RESULT_JSON is json) ENABLE, 
	 CONSTRAINT "RRL_IW_THERM_RANGE_CK" CHECK ((TASK_TEMP_MIN is null and TASK_TEMP_MAX is null)or(TASK_TEMP_MIN is not null and TASK_TEMP_MAX is not null and TASK_TEMP_MIN<=TASK_TEMP_MAX)) ENABLE, 
	 CONSTRAINT "RRL_IW_THERM_PK" PRIMARY KEY ("OPERATION_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_IW_THERM_REV_UK" UNIQUE ("PLAN_OPERATION_ID", "REVISION_NO")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


