	 CHECK (RESULT_JSON is json) ENABLE, 
	 PRIMARY KEY ("OPERATION_ID")
  USING INDEX  ENABLE, 
	 UNIQUE ("RECOVERY_OPERATION_ID")
  USING INDEX  ENABLE, 
	 UNIQUE ("ST_ID")
  USING INDEX  ENABLE, 
	 UNIQUE ("ST_IDENTIFIER")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


