   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_LOGISTICS_COST_LINE" 
   (	"OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"LOAD_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"COST_CODE" VARCHAR2(40) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CURRENCY" VARCHAR2(3) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RATE_KEY" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"VERSION_NO" NUMBER(19,0) NOT NULL ENABLE, 
	"QUANTITY" NUMBER(19,0) NOT NULL ENABLE, 
	"RATE_VALUE" NUMBER(27,9) NOT NULL ENABLE, 
	"AMOUNT" NUMBER(27,2) NOT NULL ENABLE, 
	"BASIS" VARCHAR2(20) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RATE_DATE" DATE, 
	"PERIOD_MODE" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"PERIOD_TIME_ZONE" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"PERIOD_POLICY_VERSION" NUMBER(19,0), 
	"PERIOD_KEY" VARCHAR2(10) COLLATE "USING_NLS_COMP" DEFAULT 'LEGACY' NOT NULL ENABLE, 
	 CHECK (QUANTITY>0) ENABLE, 
	 CHECK (RATE_VALUE>=0) ENABLE, 
	 CHECK (AMOUNT>=0) ENABLE, 
	 CHECK (BASIS='BOX') ENABLE, 
	 CHECK (AMOUNT=round(QUANTITY*RATE_VALUE,2)) ENABLE, 
	 CONSTRAINT "RRL_LOG_COST_PERIOD_PK" PRIMARY KEY ("OPERATION_ID", "LOAD_OPERATION_ID", "COST_CODE", "PERIOD_KEY")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_LOG_COST_PERIOD_UQ" UNIQUE ("LOAD_OPERATION_ID", "COST_CODE", "CURRENCY", "PERIOD_KEY")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


