	"ARTICLE_CODE" VARCHAR2(40) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ARTICLE_VERSION" NUMBER(19,0) NOT NULL ENABLE, 
	"ARTICLE_NAME" VARCHAR2(500) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"OBJECT_KIND" VARCHAR2(10) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"OBJECT_ID" NUMBER NOT NULL ENABLE, 
	"AMOUNT" NUMBER(27,2) NOT NULL ENABLE, 
	"CURRENCY" VARCHAR2(3) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"EXPENSE_DATE" DATE NOT NULL ENABLE, 
	"DOCUMENT_REFERENCE" VARCHAR2(255) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REASON_TEXT" VARCHAR2(2000) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ACTOR" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CREATED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	"RESULT_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ADJUSTMENT_SIGN" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CORRECTION_OF_OP" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"EXPECTED_CONFIRMED_TOTAL" NUMBER(27,2), 
	"COST_CORRECTION_OF_OP" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	 CHECK (OBJECT_KIND in('TRIP','VEHICLE')) ENABLE, 
	 CHECK (AMOUNT>0) ENABLE, 
