  CREATE TABLE "RABAEV"."RRL_MES_MOVEMENT" 
   (	"MOVEMENT_ID" NUMBER NOT NULL ENABLE, 
	"MOVEMENT_TYPE" VARCHAR2(40) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PRODUCTION_ORDER_ID" NUMBER, 
	"PROD_BATCH_ID" NUMBER, 
	"BOM_ID" NUMBER, 
	"BOM_LINE_ID" NUMBER, 
	"RAW_BATCH_ID" NUMBER, 
	"RAW_ARTICUL" VARCHAR2(40) COLLATE "USING_NLS_COMP", 
	"UID_PALLET" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"SSCC" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"QUANTITY" NUMBER, 
	"PACK_COUNT" NUMBER, 
	"UNIT_CODE" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"SOURCE_LOCATION" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"TARGET_LOCATION" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"STATUS" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'MES_POSTED' NOT NULL ENABLE, 
	"PAYLOAD_JSON" CLOB COLLATE "USING_NLS_COMP", 
	"WMS_APPLIED_AT" DATE, 
	"WMS_APPLIED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"RETRY_COUNT" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"LAST_ERROR" VARCHAR2(4000) COLLATE "USING_NLS_COMP", 
	"CREATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"UPDATED_AT" DATE, 
	"UPDATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"SOURCE_UID_PALLET" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"TARGET_UID_PALLET" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"STOCK_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"POSTED_BASE_QTY" NUMBER, 
	"STOCK_BASE_UOM" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_MES_MOVEMENT_CHK1" CHECK (MOVEMENT_TYPE in ('RAW_ISSUE_TO_PRODUCTION', 'RAW_CONSUMPTION', 'FG_LOT_RELEASE', 'FG_PALLET_RELEASE')) ENABLE, 
	 CONSTRAINT "RRL_MES_MOVEMENT_CHK2" CHECK (STATUS in ('MES_POSTED', 'PENDING_WMS_APPLY', 'APPLIED_TO_WMS', 'ERROR', 'CANCELLED')) ENABLE, 
