	"CREATION_DATE" DATE, 
	"EXPIRY_DATE" DATE, 
	"UNIT_COUNT" NUMBER, 
	"PRICE" NUMBER, 
	"PRIHOD_NAKLAD_ID" NUMBER(*,0) NOT NULL ENABLE, 
	"PRINTED" NUMBER(*,0) DEFAULT 0, 
	"KLADOVSHIK" VARCHAR2(15) COLLATE "USING_NLS_COMP", 
	"PRODUCED_DATE" DATE, 
	"MOD_ID" NUMBER(*,0), 
	"WEIGHT_BRUTTO" NUMBER, 
	"WEIGHT_TN" NUMBER, 
	"DEFECT_PERC" NUMBER DEFAULT 0, 
	"COUNT_KOR" NUMBER(*,0), 
	"DEFECT_PERC_INCOME" NUMBER, 
	"REASON_ID" NUMBER, 
	"GTD" VARCHAR2(255) COLLATE "USING_NLS_COMP", 
	"SERTIF" VARCHAR2(255) COLLATE "USING_NLS_COMP", 
	"PROD_BATCH_ID" NUMBER, 
	"SSCC" VARCHAR2(32) COLLATE "USING_NLS_COMP", 
	"MERCURY_STATUS" VARCHAR2(30) COLLATE "USING_NLS_COMP", 
	"CRPT_STATUS" VARCHAR2(30) COLLATE "USING_NLS_COMP", 
	"QUALITY_STATUS" VARCHAR2(30) COLLATE "USING_NLS_COMP", 
	"STOCK_ORIGIN_UID" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"CREATED_BY_STOCK_OP" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"STOCK_BOX_FACTOR" NUMBER, 
	"STOCK_PACK_BASE_UOM" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"STOCK_PACK_FROZEN" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"HU_KIND" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'STOCK' NOT NULL ENABLE, 
	"HU_TYPE" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"HU_CONTENT_VERSION" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"HU_CURRENT_CELL" VARCHAR2(60) COLLATE "USING_NLS_COMP", 
	"HU_TARE_WEIGHT_KG" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"HU_SHIPPED_OPERATION" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"STOCK_COMPOSITION_VERSION" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	 CONSTRAINT "RRL_PALLET_PACK_CHK" CHECK (STOCK_PACK_FROZEN in(0,1) and
 (STOCK_BOX_FACTOR is null or (STOCK_BOX_FACTOR>=1 and STOCK_BOX_FACTOR=trunc(STOCK_BOX_FACTOR) and STOCK_BOX_FACTOR<=1000000000)) and
 (STOCK_PACK_FROZEN=0 or STOCK_PACK_BASE_UOM is not null)) ENABLE, 
	 CONSTRAINT "RRL_PALLET_HU_KIND_CK" CHECK (HU_KIND in('STOCK','CONTAINER') and HU_CONTENT_VERSION>=0 and HU_CONTENT_VERSION=trunc(HU_CONTENT_VERSION) and HU_TARE_WEIGHT_KG>=0 and (HU_KIND='STOCK' or (ARTICUL is null and UNIT_COUNT=0 and HU_TYPE in('PALLET','BOX','ROLL_CAGE','BAG') and ((HU_SHIPPED_OPERATION is null and HU_CURRENT_CELL is not null) or (HU_SHIPPED_OPERATION is not null and HU_CURRENT_CELL is null))))) ENABLE, 
	 CHECK (STOCK_COMPOSITION_VERSION>=0 and STOCK_COMPOSITION_VERSION=trunc(STOCK_COMPOSITION_VERSION)) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;
