	"REPLENISHMENT_QTY_MODE" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'FILL_TO_VOLUME' NOT NULL ENABLE, 
	"MIN_TRIGGER_BOX_QTY" NUMBER, 
	"MIN_TRIGGER_LAYER_QTY" NUMBER, 
	"BOXES_PER_LAYER" NUMBER, 
	"BOXES_PER_PALLET" NUMBER, 
	"BOX_VOLUME_M3" NUMBER, 
	"ALLOW_PARTIAL_PALLET" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"USE_ARTICUL_REPLENISH_RULE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"REPLENISHMENT_RELEASE_POLICY" VARCHAR2(40) COLLATE "USING_NLS_COMP" DEFAULT 'LAYER_TRIGGER' NOT NULL ENABLE, 
	"SAFETY_LAYER_QTY" NUMBER, 
	"PREDICTIVE_BUFFER_MIN" NUMBER, 
	"PICK_RATE_SOURCE" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'MIXED' NOT NULL ENABLE, 
	"RECHECK_ON_PICK_EVENT" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "RRL_PICK_FACE_ARTICUL_CHK1" CHECK (CASE_PICK_ENABLED in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_PICK_FACE_ARTICUL_CHK2" CHECK (ACTIVE in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_PICK_FACE_ARTICUL_PK" PRIMARY KEY ("PICK_FACE_ARTICUL_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_PICK_FACE_ART_CHK3" CHECK (REPLENISHMENT_METHOD in ('IMMEDIATE', 'MINIMAX')) ENABLE, 
	 CONSTRAINT "RRL_PICK_FACE_ART_CHK4" CHECK (REPLENISHMENT_QTY_MODE in ('FULL_PALLET', 'HALF_PALLET', 'FILL_TO_VOLUME')) ENABLE, 
	 CONSTRAINT "RRL_PICK_FACE_ART_CHK5" CHECK (ALLOW_PARTIAL_PALLET in (0, 1)) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_PICK_FACE_ASSIGNMENT" 
   (	"PICK_FACE_ASSIGNMENT_ID" NUMBER NOT NULL ENABLE, 
