	 CONSTRAINT "RRL_PICK_WAVE_REPL_CHK3" CHECK (REPLENISHMENT_QTY_MODE is null or REPLENISHMENT_QTY_MODE in ('FULL_PALLET', 'HALF_PALLET', 'FILL_TO_VOLUME')) ENABLE, 
	 CONSTRAINT "RRL_PICK_WAVE_REPL_CHK1" CHECK (STATUS in (
      'NEW',
      'QUEUED',
      'WAIT_FREE_CELL',
      'WAIT_MINIMAX',
      'RELEASED',
      'ASSIGNED',
      'IN_PROGRESS',
      'DONE',
      'CANCELLED',
      'FAILED'
    )) ENABLE
