  CREATE TABLE "RABAEV"."RRL_PICK_WEIGHT_CHOICE" 
   (	"CHOICE_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"CUSTOMER_ORDER_ROW_ID" NUMBER NOT NULL ENABLE, 
	"CUSTOMER_ORDER_ID" NUMBER NOT NULL ENABLE, 
	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"ARTICLE" VARCHAR2(160) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PHYSICAL_UNIT_KEY" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SOURCE_UID" VARCHAR2(150) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SOURCE_CELL" VARCHAR2(60) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"STOCK_VERSION" NUMBER NOT NULL ENABLE, 
	"NET_WEIGHT_KG" NUMBER(27,9) NOT NULL ENABLE, 
	"POLICY_VERSION" NUMBER NOT NULL ENABLE, 
	"TOLERANCE_PCT" NUMBER(5,2) NOT NULL ENABLE, 
	"ORIGINAL_ORDER_KG" NUMBER(27,9) NOT NULL ENABLE, 
	"ORIGINAL_REMAINING_KG" NUMBER(27,9) NOT NULL ENABLE, 
	"CHOICE_MODE" VARCHAR2(24) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"STATUS" VARCHAR2(16) COLLATE "USING_NLS_COMP" DEFAULT 'ACCEPTED' NOT NULL ENABLE, 
	"APPROVED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"APPROVED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	"REASON_TEXT" VARCHAR2(1000 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SOURCE_SIGNATURE" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SOURCE_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REQUEST_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RESULT_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PICK_PLAN_ID" NUMBER, 
	"PICK_PLAN_LINE_ID" NUMBER, 
	"USED_AT" TIMESTAMP (6) WITH TIME ZONE, 
	"CANCELLED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"CANCELLED_AT" TIMESTAMP (6) WITH TIME ZONE, 
	"CANCEL_REASON" VARCHAR2(1000 CHAR) COLLATE "USING_NLS_COMP", 
	 CHECK (NET_WEIGHT_KG>0) ENABLE, 
	 CHECK (TOLERANCE_PCT between 0 and 100) ENABLE, 
	 CHECK (ORIGINAL_ORDER_KG>0) ENABLE, 
	 CHECK (ORIGINAL_REMAINING_KG>0) ENABLE, 
	 CHECK (CHOICE_MODE in('WITHIN_TOLERANCE','LAST_WHOLE_BOX')) ENABLE, 
	 CHECK (STATUS in('ACCEPTED','USED','CANCELLED')) ENABLE, 
	 CHECK (SOURCE_JSON is json) ENABLE, 
	 CHECK (REQUEST_JSON is json) ENABLE, 
	 CHECK (RESULT_JSON is json) ENABLE, 
	 PRIMARY KEY ("CHOICE_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


