  CREATE TABLE "RABAEV"."RRL_QC_SCOPE_RULE" 
   (	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"STORE_ADDR" VARCHAR2(255) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PLACE_CATEGORY" VARCHAR2(10) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RULE_VERSION" NUMBER NOT NULL ENABLE, 
	"ACTIVE_FLAG" NUMBER(1,0) NOT NULL ENABLE, 
	"CONTROL_MODE" VARCHAR2(10) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"INDEPENDENT_FLAG" NUMBER(1,0) NOT NULL ENABLE, 
	"SAMPLE_PERCENT" NUMBER(5,2) NOT NULL ENABLE, 
	"EXEMPT_WHOLE" NUMBER(1,0) NOT NULL ENABLE, 
	"EXEMPT_STORAGE" NUMBER(1,0) NOT NULL ENABLE, 
	"UPDATED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"UPDATED_AT" TIMESTAMP (6) DEFAULT systimestamp NOT NULL ENABLE, 
	 CHECK (PLACE_CATEGORY in('ANY','STOCK','CASE')) ENABLE, 
	 CHECK (RULE_VERSION>=1) ENABLE, 
	 CHECK (ACTIVE_FLAG in(0,1)) ENABLE, 
	 CHECK (CONTROL_MODE in('NONE','ANY','SCAN','WEIGHT','BOTH')) ENABLE, 
	 CHECK (INDEPENDENT_FLAG in(0,1)) ENABLE, 
	 CHECK (SAMPLE_PERCENT between 0 and 100) ENABLE, 
	 CHECK (EXEMPT_WHOLE in(0,1)) ENABLE, 
	 CHECK (EXEMPT_STORAGE in(0,1)) ENABLE, 
	 CONSTRAINT "RRL_QC_SCOPE_RULE_PK" PRIMARY KEY ("WARE_ID", "STORE_ADDR", "PLACE_CATEGORY")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


