   (	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"COMPANY_PREFIX" VARCHAR2(12) COLLATE "USING_NLS_COMP", 
	"EXTENSION_DIGIT" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE, 
	"COORDINATE_UNIT_M" NUMBER DEFAULT 1 NOT NULL ENABLE, 
	"REACHTRUCK_MPS" NUMBER DEFAULT 1 NOT NULL ENABLE, 
	"LIFT_MPS" NUMBER DEFAULT 0.5 NOT NULL ENABLE, 
	"PLACEMENT_METRIC" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'DISTANCE' NOT NULL ENABLE, 
	"UPDATED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"UPDATED_AT" TIMESTAMP (6) DEFAULT systimestamp, 
	"HU_CELL_HEIGHT_UNIT" VARCHAR2(2) COLLATE "USING_NLS_COMP", 
	"OUTGOING_QC_MODE" VARCHAR2(10) COLLATE "USING_NLS_COMP", 
	"OUTGOING_QC_INDEPENDENT" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"OUTGOING_QC_SAMPLE_PERCENT" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"DEFER_WAIT_CELL" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_REC_WSET_SPEED_CK" CHECK (COORDINATE_UNIT_M>0 and REACHTRUCK_MPS>0 and LIFT_MPS>0) ENABLE, 
	 CONSTRAINT "RRL_REC_WSET_METRIC_CK" CHECK (PLACEMENT_METRIC in('DISTANCE','TIME')) ENABLE, 
	 CONSTRAINT "RRL_REC_WSET_EXT_CK" CHECK (EXTENSION_DIGIT between 0 and 9) ENABLE, 
