  CREATE TABLE "RABAEV"."RRL_STOCK_RESERVATION" 
   (	"RESERVATION_ID" NUMBER NOT NULL ENABLE, 
	"RESERVATION_KIND" VARCHAR2(10) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RESERVATION_SCOPE" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'QTY' NOT NULL ENABLE, 
	"RESERVATION_DOMAIN" VARCHAR2(30) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SOURCE_DOC_TYPE" VARCHAR2(40) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SOURCE_DOC_ID" NUMBER NOT NULL ENABLE, 
	"SOURCE_LINE_ID" NUMBER, 
	"TASK_ID" NUMBER, 
	"CUSTOMER_ID" NUMBER, 
	"CUSTOMER_ORDER_ID" NUMBER, 
	"PRODUCTION_ORDER_ID" NUMBER, 
	"PICK_PLAN_ID" NUMBER, 
	"PICK_PLAN_LINE_ID" NUMBER, 
	"PICK_WAVE_ID" NUMBER, 
	"PICK_WAVE_LINE_ID" NUMBER, 
	"ARTICUL" VARCHAR2(40) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"QTY" NUMBER NOT NULL ENABLE, 
	"UNIT_CODE" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"WARE_ID" NUMBER, 
	"CELL" VARCHAR2(80) COLLATE "USING_NLS_COMP", 
	"BATCH_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"PROD_BATCH_ID" NUMBER, 
	"UID_PALLET" VARCHAR2(128) COLLATE "USING_NLS_COMP", 
	"SSCC" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"STATUS" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'ACTIVE' NOT NULL ENABLE, 
	"PRIORITY" NUMBER DEFAULT 100 NOT NULL ENABLE, 
	"LOCK_OWNER" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"LOCKED_AT" TIMESTAMP (6), 
	"CREATED_AT" TIMESTAMP (6) DEFAULT systimestamp NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"RELEASED_AT" TIMESTAMP (6), 
	"RELEASED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"RELEASE_REASON" VARCHAR2(1000) COLLATE "USING_NLS_COMP", 
	"CONSUMED_AT" TIMESTAMP (6), 
	"CONSUMED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"LAST_ERROR" VARCHAR2(2000) COLLATE "USING_NLS_COMP", 
	"CELL_SLOT_ID" NUMBER, 
	"BASE_QTY" NUMBER, 
	"BASE_UOM" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"RESERVATION_VERSION" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"POOL_WARE_ID" NUMBER, 
	 CONSTRAINT "RRL_STOCK_RES_KIND_CHK" CHECK (RESERVATION_KIND in ('SOFT', 'HARD')) ENABLE, 
	 CONSTRAINT "RRL_STOCK_RES_SCOPE_CHK" CHECK (RESERVATION_SCOPE in ('PALLET', 'QTY')) ENABLE, 
	 CONSTRAINT "RRL_STOCK_RES_STATUS_CHK" CHECK (STATUS in ('ACTIVE', 'ALLOCATED', 'PICKING', 'CONSUMED', 'RELEASED', 'CANCELLED', 'EXPIRED')) ENABLE, 
	 CONSTRAINT "RRL_STOCK_RES_DOMAIN_CHK" CHECK (RESERVATION_DOMAIN in ('MES_RAW', 'PICKING', 'WAVE', 'SHIPMENT')) ENABLE, 
	 CONSTRAINT "RRL_STOCK_RES_QTY_CHK" CHECK (QTY >= 0) ENABLE, 
	 CONSTRAINT "RRL_STOCK_RES_SOFT_CHK" CHECK (
        RESERVATION_KIND <> 'SOFT'
        or (WARE_ID is null and CELL is null and BATCH_ID is null and PROD_BATCH_ID is null and UID_PALLET is null and SSCC is null)
      ) ENABLE, 
	 CONSTRAINT "RRL_STOCK_RES_HARD_CHK" CHECK (
        RESERVATION_KIND <> 'HARD'
        or (WARE_ID is not null and CELL is not null and (UID_PALLET is not null or BATCH_ID is not null or PROD_BATCH_ID is not null))
      ) ENABLE, 
	 CONSTRAINT "RRL_STOCK_RESERVATION_PK" PRIMARY KEY ("RESERVATION_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


