	"CASE_VERSION" NUMBER(19,0) DEFAULT 1 NOT NULL ENABLE, 
	"EXPEDITION_USER" NVARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"SECURITY_USER" NVARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"SEARCH_DEADLINE" TIMESTAMP (6) WITH TIME ZONE, 
