  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_STORE_MEDIA_ASSET" 
   (	"SHA256" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"MIME_TYPE" VARCHAR2(20) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BYTE_COUNT" NUMBER NOT NULL ENABLE, 
	"WIDTH_PX" NUMBER NOT NULL ENABLE, 
	"HEIGHT_PX" NUMBER NOT NULL ENABLE, 
	"CONTENT_BYTES" BLOB NOT NULL ENABLE, 
	"CREATED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	 CHECK (MIME_TYPE in('image/jpeg','image/png')) ENABLE, 
	 CHECK (BYTE_COUNT>0 and BYTE_COUNT<=4194304) ENABLE, 
	 CHECK (WIDTH_PX>0) ENABLE, 
	 CHECK (HEIGHT_PX>0) ENABLE, 
	 CONSTRAINT "RRL_STORE_MEDIA_PIXELS_CK" CHECK (WIDTH_PX*HEIGHT_PX<=12000000) ENABLE, 
	 PRIMARY KEY ("SHA256")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_STORE_PROFILE" 
   (	"STORE_ADDR" VARCHAR2(255) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PROFILE_VERSION" NUMBER NOT NULL ENABLE, 
	"RECEIVING_WINDOW_MODE" VARCHAR2(12) COLLATE "USING_NLS_COMP" DEFAULT 'UNCONFIGURED' NOT NULL ENABLE, 
	"TIMEZONE_REGION" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"BACKROOM_FLAG" NUMBER(1,0), 
	"BACKROOM_PALLETS" NUMBER(6,0), 
	"BACKROOM_ROLLS" NUMBER(6,0), 
	"UNATTENDED_DROP_FLAG" NUMBER(1,0), 
	"STORAGE_TEMP_CLASS" VARCHAR2(10) COLLATE "USING_NLS_COMP", 
	"RAMP_FLAG" NUMBER(1,0), 
	"RAMP_HEIGHT_MM" NUMBER(6,0), 
	"MAX_VEHICLE_OUTER_HEIGHT_MM" NUMBER(6,0), 
	"MAX_VEHICLE_OUTER_LENGTH_MM" NUMBER(6,0), 
	"DEFAULT_UNLOAD_METHOD" VARCHAR2(10) COLLATE "USING_NLS_COMP", 
	"LOADER_REQUIRED" NUMBER(1,0), 
	"ACCESS_NOTE" VARCHAR2(1000 CHAR) COLLATE "USING_NLS_COMP", 
	"UPDATED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"UPDATED_AT" TIMESTAMP (6) DEFAULT systimestamp NOT NULL ENABLE, 
	 CHECK (PROFILE_VERSION>=1) ENABLE, 
	 CHECK (RECEIVING_WINDOW_MODE in('UNCONFIGURED','WEEKLY')) ENABLE, 
	 CHECK (BACKROOM_FLAG in(0,1)) ENABLE, 
	 CHECK (BACKROOM_PALLETS between 0 and 100000) ENABLE, 
	 CHECK (BACKROOM_ROLLS between 0 and 100000) ENABLE, 
	 CHECK (UNATTENDED_DROP_FLAG in(0,1)) ENABLE, 
	 CHECK (STORAGE_TEMP_CLASS in('AMBIENT','CHILLED','FROZEN')) ENABLE, 
	 CHECK (RAMP_FLAG in(0,1)) ENABLE, 
	 CHECK (RAMP_HEIGHT_MM between 0 and 100000) ENABLE, 
	 CHECK (MAX_VEHICLE_OUTER_HEIGHT_MM between 1 and 100000) ENABLE, 
	 CHECK (MAX_VEHICLE_OUTER_LENGTH_MM between 1 and 100000) ENABLE, 
	 CHECK (DEFAULT_UNLOAD_METHOD in('PALLET','ROLL_CAGE','MANUAL')) ENABLE, 
	 CHECK (LOADER_REQUIRED in(0,1)) ENABLE, 
	 CONSTRAINT "RRL_STORE_PROFILE_BACKROOM_CK" CHECK (not(BACKROOM_FLAG=0 and(nvl(BACKROOM_PALLETS,0)>0 or nvl(BACKROOM_ROLLS,0)>0))) ENABLE, 
	 CONSTRAINT "RRL_STORE_PROFILE_RAMP_CK" CHECK (not(RAMP_FLAG=0 and nvl(RAMP_HEIGHT_MM,0)>0)) ENABLE, 
	 CONSTRAINT "RRL_STORE_PROFILE_TZ_CK" CHECK (RECEIVING_WINDOW_MODE!='WEEKLY' or TIMEZONE_REGION is not null) ENABLE, 
	 CONSTRAINT "RRL_STORE_PROFILE_PK" PRIMARY KEY ("STORE_ADDR")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_STORE_PROFILE_CHANGE" 
   (	"OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"STORE_ADDR" VARCHAR2(255) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PROFILE_VERSION" NUMBER NOT NULL ENABLE, 
	"ACTOR" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REASON_TEXT" VARCHAR2(1000 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REQUEST_HASH" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REQUEST_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RESULT_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CREATED_AT" TIMESTAMP (6) DEFAULT systimestamp NOT NULL ENABLE, 
	 CHECK (REQUEST_JSON is json) ENABLE, 
	 CHECK (RESULT_JSON is json) ENABLE, 
	 PRIMARY KEY ("OPERATION_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_STORE_PROFILE_CHANGE_U1" UNIQUE ("STORE_ADDR", "PROFILE_VERSION")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


