   (	"OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"LOAD_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"STORE_ADDR" VARCHAR2(255) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ROOT_KEY" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
