	"COMPOSITION_SIGNATURE" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"COMPOSITION_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RECEIVED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
