  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_STORE_RECEIPT_LINE" 
   (	"OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"LINE_NO" NUMBER NOT NULL ENABLE, 
	"LOT_UID" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ARTICLE" VARCHAR2(160) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BASE_UOM" VARCHAR2(20) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SHIPPED_BASE_QTY" NUMBER(27,9) NOT NULL ENABLE, 
	"ACCEPTED_BASE_QTY" NUMBER(27,9) NOT NULL ENABLE, 
	"MISSING_BASE_QTY" NUMBER(27,9) DEFAULT 0 NOT NULL ENABLE, 
	"REFUSED_BASE_QTY" NUMBER(27,9) DEFAULT 0 NOT NULL ENABLE, 
	"DAMAGED_BASE_QTY" NUMBER(27,9) DEFAULT 0 NOT NULL ENABLE, 
	"REPORTED_EXTRA_BASE_QTY" NUMBER(27,9) DEFAULT 0 NOT NULL ENABLE, 
	 CHECK (SHIPPED_BASE_QTY>0) ENABLE, 
	 CHECK (ACCEPTED_BASE_QTY>=0) ENABLE, 
	 CHECK (MISSING_BASE_QTY>=0) ENABLE, 
	 CHECK (REFUSED_BASE_QTY>=0) ENABLE, 
	 CHECK (DAMAGED_BASE_QTY>=0) ENABLE, 
	 CONSTRAINT "RRL_STORE_RECEIPT_QTY_CK" CHECK (SHIPPED_BASE_QTY=ACCEPTED_BASE_QTY+MISSING_BASE_QTY+REFUSED_BASE_QTY+DAMAGED_BASE_QTY) ENABLE, 
	 CONSTRAINT "RRL_STORE_RECEIPT_LINE_PK" PRIMARY KEY ("OPERATION_ID", "LINE_NO")
  USING INDEX  ENABLE, 
	 CHECK (REPORTED_EXTRA_BASE_QTY>=0) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_STORE_RECEIPT_PHOTO" 
   (	"PHOTO_ID" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
