	"VIEW_CODE" VARCHAR2(10) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ASSET_SHA256" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
