	"FROM_MINUTE" NUMBER(4,0) NOT NULL ENABLE, 
	"TO_MINUTE" NUMBER(4,0) NOT NULL ENABLE, 
	 CHECK (WEEKDAY between 1 and 7) ENABLE, 
	 CHECK (FROM_MINUTE between 0 and 1439) ENABLE, 
	 CHECK (TO_MINUTE between 1 and 1440) ENABLE, 
	 CONSTRAINT "RRL_STORE_RECEIVING_WINDOW_CK" CHECK (FROM_MINUTE<TO_MINUTE) ENABLE, 
	 CONSTRAINT "RRL_STORE_RECEIVING_WINDOW_PK" PRIMARY KEY ("STORE_ADDR", "WEEKDAY", "FROM_MINUTE")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


