	"LINE_NO" NUMBER(10,0) NOT NULL ENABLE, 
	"LOT_UID" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ARTICLE" VARCHAR2(160) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BASE_UOM" VARCHAR2(20) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BASE_QTY" NUMBER(27,9) NOT NULL ENABLE, 
	"DISPOSITION" VARCHAR2(20) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REASON_TEXT" VARCHAR2(2000) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"DECISION_REFERENCE" VARCHAR2(255) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"COMPLETE_GOOD_BOX" NUMBER(1,0) NOT NULL ENABLE, 
	"APPROVED_BY" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"APPROVED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	"RETURN_BASIS" VARCHAR2(10) COLLATE "USING_NLS_COMP" DEFAULT 'ACCEPTED' NOT NULL ENABLE, 
	 CHECK (BASE_QTY>0) ENABLE, 
	 CHECK (DISPOSITION in('REUSE','SUPPLIER','DISPOSAL')) ENABLE, 
	 CHECK (COMPLETE_GOOD_BOX in(0,1)) ENABLE, 
