	"RECEIVE_CELL" VARCHAR2(60) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ARTICLE" VARCHAR2(160) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BASE_QTY" NUMBER(27,9) NOT NULL ENABLE, 
	"BASE_UOM" VARCHAR2(20) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"DISPOSITION" VARCHAR2(20) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"OBSERVED_BATCH" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BATCH_SOURCE" VARCHAR2(30) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"EXPIRY_DATE" DATE NOT NULL ENABLE, 
	"GROSS_WEIGHT_KG" NUMBER(27,9) NOT NULL ENABLE, 
	"NET_WEIGHT_KG" NUMBER(27,9) NOT NULL ENABLE, 
