	 UNIQUE ("PICKUP_OPERATION_ID")
  USING INDEX  ENABLE, 
	 UNIQUE ("APPROVAL_OPERATION_ID")
  USING INDEX  ENABLE, 
	 UNIQUE ("UID_PALLET")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_STORE_RETURN_RECEIPT_DOC_UQ" UNIQUE ("NAKLAD_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_STORE_RETURN_DISPOSITION_CK" CHECK (DISPOSITION in('REUSE','SUPPLIER','DISPOSAL')) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


