   (	"OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"PAYLOAD_HASH" RAW(32) NOT NULL ENABLE, 
	"DISPATCH_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"DOCUMENT_REFERENCE" VARCHAR2(255) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"DOCUMENT_SHA256" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
