	 PRIMARY KEY ("BALANCE_KEY")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_TARE_BALANCE_UQ" UNIQUE ("OWNER_WARE_ID", "PALLET_TYPE_ID", "CONDITION_CODE", "CUSTODIAN_KIND", "CUSTODIAN_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_TARE_BOOK" 
   (	"OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"BALANCE_KEY" RAW(32) NOT NULL ENABLE, 
	"OWNER_WARE_ID" NUMBER NOT NULL ENABLE, 
	"PALLET_TYPE_ID" NUMBER NOT NULL ENABLE, 
	"PLACE_KIND" VARCHAR2(6) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PLACE_ID" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"STATUS" VARCHAR2(12) COLLATE "USING_NLS_COMP" DEFAULT 'HELD' NOT NULL ENABLE, 
	"QUANTITY" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CREATED_BY" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CREATED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	"CLOSED_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"CLOSED_BY" NVARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"CLOSED_AT" TIMESTAMP (6) WITH TIME ZONE, 
	 CHECK (PLACE_KIND in('CASE','HU')) ENABLE, 
	 CHECK (STATUS in('HELD','CANCELLED','TRANSFERRED')) ENABLE, 
	 CHECK (QUANTITY=1) ENABLE, 
	 CHECK ((STATUS='HELD' and CLOSED_OPERATION_ID is null and CLOSED_BY is null and CLOSED_AT is null)or(STATUS!='HELD' and CLOSED_OPERATION_ID is not null and CLOSED_BY is not null and CLOSED_AT is not null)) ENABLE, 
	 PRIMARY KEY ("OPERATION_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


