	"FROM_BALANCE_KEY" RAW(32), 
	"TO_BALANCE_KEY" RAW(32) NOT NULL ENABLE, 
	"QUANTITY" NUMBER(18,0) NOT NULL ENABLE, 
	"BEFORE_QTY" NUMBER(18,0), 
	"AFTER_QTY" NUMBER(18,0), 
	"REASON_TEXT" VARCHAR2(2000) COLLATE "USING_NLS_COMP", 
	"DECISION_REFERENCE" VARCHAR2(255) COLLATE "USING_NLS_COMP", 
	"ACTOR" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CREATED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	 CHECK (ACTION_KIND in('COUNT','TRANSFER')) ENABLE, 
	 CHECK ((ACTION_KIND='COUNT' and BEFORE_QTY is not null and AFTER_QTY is not null and REASON_TEXT is not null and DECISION_REFERENCE is not null) or(ACTION_KIND='TRANSFER' and FROM_BALANCE_KEY is not null and QUANTITY>0)) ENABLE, 
