	"DECISION_REFERENCE" VARCHAR2(255) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ACTOR" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
