  CREATE TABLE "RABAEV"."RRL_TARE_RESOLUTION" 
   (	"OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"RESOLUTION_KIND" VARCHAR2(12) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"OWNER_WARE_ID" NUMBER NOT NULL ENABLE, 
	"PALLET_TYPE_ID" NUMBER NOT NULL ENABLE, 
	"CUSTODIAN_KIND" VARCHAR2(12) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CUSTODIAN_ID" VARCHAR2(255) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"FROM_BALANCE_KEY" RAW(32) NOT NULL ENABLE, 
	"TO_BALANCE_KEY" RAW(32), 
	"QUANTITY" NUMBER(18,0) NOT NULL ENABLE, 
	"DELIVERY_ACCEPT_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"DAMAGE_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"REASON_TEXT" VARCHAR2(2000) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"DECISION_REFERENCE" VARCHAR2(255) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ACTOR" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CREATED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	 CHECK (RESOLUTION_KIND in('DAMAGE','WRITE_OFF')) ENABLE, 
	 CHECK (CUSTODIAN_KIND in('WAREHOUSE','VEHICLE','STORE')) ENABLE, 
	 CHECK (QUANTITY>0) ENABLE, 
	 CHECK ((RESOLUTION_KIND='DAMAGE' and TO_BALANCE_KEY is not null and DAMAGE_OPERATION_ID is null)or(RESOLUTION_KIND='WRITE_OFF' and TO_BALANCE_KEY is null and DAMAGE_OPERATION_ID is not null)) ENABLE, 
	 CHECK (CUSTODIAN_KIND!='STORE' or DELIVERY_ACCEPT_OPERATION_ID is not null) ENABLE, 
	 PRIMARY KEY ("OPERATION_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_TARE_RETURN_POLICY" 
   (	"SCOPE_KIND" VARCHAR2(10) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SCOPE_KEY" VARCHAR2(255) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RETURN_MODE" VARCHAR2(16) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RETURN_DAYS" NUMBER(4,0), 
	"TIMEZONE_REGION" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"POLICY_VERSION" NUMBER(19,0) NOT NULL ENABLE, 
	"CHANGED_BY" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CHANGED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	 CHECK (SCOPE_KIND in('STORE','CUSTOMER')) ENABLE, 
	 CHECK (RETURN_MODE in('NEXT_DELIVERY','DAYS','SAME_DAY')) ENABLE, 
	 CHECK (POLICY_VERSION>=1) ENABLE, 
	 CHECK ((RETURN_MODE='DAYS' and RETURN_DAYS between 1 and 3660)or(RETURN_MODE!='DAYS' and RETURN_DAYS is null)) ENABLE, 
	 CONSTRAINT "RRL_TARE_RETURN_POLICY_PK" PRIMARY KEY ("SCOPE_KIND", "SCOPE_KEY")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


