	"UNIT_KEYS_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PROFILE_SIGNATURE" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"STOCK_VERSION" NUMBER NOT NULL ENABLE, 
	"SOURCE_UID" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SOURCE_CELL" VARCHAR2(15) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
