	 CONSTRAINT "RRL_TASK_SCAN_DRAFT_PK" PRIMARY KEY ("DRAFT_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_TOPOLOGY_AISLE" 
   (	"TOPOLOGY_AISLE_ID" NUMBER NOT NULL ENABLE, 
	"TOPOLOGY_ID" NUMBER NOT NULL ENABLE, 
	"ZONE_CODE" VARCHAR2(40) COLLATE "USING_NLS_COMP", 
	"AISLE_CODE" VARCHAR2(40) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"AISLE_NAME" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"AISLE_KIND" VARCHAR2(40) COLLATE "USING_NLS_COMP" DEFAULT 'PICK_AISLE' NOT NULL ENABLE, 
	"DIRECTION_CODE" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'BOTH' NOT NULL ENABLE, 
	"X1" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"Y1" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"X2" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"Y2" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"WIDTH_M" NUMBER DEFAULT 3 NOT NULL ENABLE, 
	"ALLOW_PICKER" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"ALLOW_REACHTRUCK" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"ACTIVE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CREATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"UPDATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"UPDATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_TOPOLOGY_AISLE_CHK1" CHECK (ACTIVE in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_TOPOLOGY_AISLE_PK" PRIMARY KEY ("TOPOLOGY_AISLE_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_TOPOLOGY_AISLE_U1" UNIQUE ("TOPOLOGY_ID", "AISLE_CODE")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


