	"ROUTE_KIND" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'TOPOLOGY_ESTIMATE' NOT NULL ENABLE, 
	"CALC_METHOD" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'MANHATTAN' NOT NULL ENABLE, 
	"ACTIVE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
