   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_TOPOLOGY_CELL_SLOT" 
   (	"CELL_SLOT_ID" NUMBER NOT NULL ENABLE, 
	"TOPOLOGY_ID" NUMBER NOT NULL ENABLE, 
	"TOPOLOGY_CELL_ID" NUMBER NOT NULL ENABLE, 
	"PARENT_SLOT_LAYER_KIND" VARCHAR2(30) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SLOT_KIND" VARCHAR2(30) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SLOT_CODE" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SLOT_NAME" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"FRACTION_COUNT" NUMBER DEFAULT 1 NOT NULL ENABLE, 
	"FRACTION_INDEX" NUMBER DEFAULT 1 NOT NULL ENABLE, 
	"SUB_LEVEL_NO" NUMBER, 
	"SUB_COLUMN_NO" NUMBER, 
	"PICK_ORDER" NUMBER, 
	"STORAGE_ORDER" NUMBER, 
	"CAPACITY_QTY" NUMBER, 
	"CAPACITY_VOLUME_M3" NUMBER, 
	"CAPACITY_WEIGHT_KG" NUMBER, 
	"X_OFFSET_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"Y_OFFSET_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"Z_OFFSET_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"WIDTH_M" NUMBER, 
	"DEPTH_M" NUMBER, 
	"HEIGHT_M" NUMBER, 
	"CANVAS_OBJECT_ID" NUMBER, 
	"ACTIVE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CREATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"UPDATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"UPDATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_TOPO_CELL_SLOT_CHK_KIND" CHECK (
        PARENT_SLOT_LAYER_KIND in ('PICK_FACE_SLOT', 'STORAGE_SLOT', 'MIXED') and
        SLOT_KIND in ('PICK_FACE_SLOT', 'STORAGE_SLOT') and
        (PARENT_SLOT_LAYER_KIND = 'MIXED' or PARENT_SLOT_LAYER_KIND = SLOT_KIND)
      ) ENABLE, 
	 CONSTRAINT "RRL_TOPO_CELL_SLOT_CHK_FRACT" CHECK (
        FRACTION_COUNT between 1 and 9 and
        FRACTION_INDEX between 1 and FRACTION_COUNT
      ) ENABLE, 
	 CONSTRAINT "RRL_TOPO_CELL_SLOT_CHK_ORD" CHECK (
        (SLOT_KIND = 'PICK_FACE_SLOT' and STORAGE_ORDER is null) or
        (SLOT_KIND = 'STORAGE_SLOT' and PICK_ORDER is null)
      ) ENABLE, 
	 CONSTRAINT "RRL_TOPO_CELL_SLOT_CHK_SIZE" CHECK (
        (WIDTH_M is null or WIDTH_M > 0) and
        (DEPTH_M is null or DEPTH_M > 0) and
        (HEIGHT_M is null or HEIGHT_M > 0) and
        (CAPACITY_QTY is null or CAPACITY_QTY >= 0) and
        (CAPACITY_VOLUME_M3 is null or CAPACITY_VOLUME_M3 >= 0) and
        (CAPACITY_WEIGHT_KG is null or CAPACITY_WEIGHT_KG >= 0)
      ) ENABLE, 
	 CONSTRAINT "RRL_TOPO_CELL_SLOT_CHK_ACTIVE" CHECK (ACTIVE in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_TOPO_CELL_SLOT_PK" PRIMARY KEY ("CELL_SLOT_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


