	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"STATUS" VARCHAR2(15) COLLATE "USING_NLS_COMP" DEFAULT 'LOADED' NOT NULL ENABLE, 
	"GROSS_WEIGHT_KG" NUMBER(27,9) NOT NULL ENABLE, 
	"BOUNDING_VOLUME_M3" NUMBER(27,9) NOT NULL ENABLE, 
	"CONTENT_VERSION" NUMBER(19,0) NOT NULL ENABLE, 
	"COMPOSITION_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"LOADED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"LOADED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	"DEPARTURE_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"DEPARTED_AT" TIMESTAMP (6) WITH TIME ZONE, 
	"ROOT_CASE_TASK_ID" NUMBER(10,0), 
	"CUSTODY_RELEASED_AT" TIMESTAMP (6) WITH TIME ZONE, 
	"CUSTODY_RELEASE_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	 CHECK (STATUS in('LOADED','UNLOADED','DEPARTED')) ENABLE, 
	 CHECK (GROSS_WEIGHT_KG>0) ENABLE, 
	 CHECK (BOUNDING_VOLUME_M3>0) ENABLE, 
	 CHECK (COMPOSITION_JSON is json) ENABLE, 
	 PRIMARY KEY ("LOAD_OPERATION_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_TT_LOAD_OWNER_CK" CHECK ((ROOT_UID is not null and ROOT_CASE_TASK_ID is null) or(ROOT_UID is null and ROOT_CASE_TASK_ID is not null)) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


