  CREATE TABLE "RABAEV"."RRL_TT_LOAD_BOX_WEIGHT" 
   (	"LOAD_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BOX_UID" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BOX_CONTENT_VERSION" NUMBER(19,0) NOT NULL ENABLE, 
	"GROSS_WEIGHT_KG" NUMBER(27,9) NOT NULL ENABLE, 
	"MEASUREMENT_ORIGIN" VARCHAR2(30) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"MEASUREMENT_REF" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SCAN_IDENTIFIER" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RECORDED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RECORDED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	"CASE_BOX_TASK_ID" NUMBER, 
	"FINAL_SCALE_CAPTURE" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"WAREHOUSE_QC_OPERATION" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"TARE_WEIGHT_KG" NUMBER(27,9), 
	"NET_WEIGHT_KG" NUMBER(27,9), 
	"DEVICE_MODE" VARCHAR2(10) COLLATE "USING_NLS_COMP", 
	"COMPOSITION_SIGNATURE" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"SIGNATURE_VERSION" NUMBER(2,0), 
	"MEASURED_CONTENT_VERSION" NUMBER, 
	"COVERAGE_COMPLETE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"PALLET_BOX_UID" VARCHAR2(200) COLLATE "USING_NLS_COMP" GENERATED ALWAYS AS (CASE  WHEN "CASE_BOX_TASK_ID" IS NULL THEN "BOX_UID" ELSE NULL END) VIRTUAL , 
	 CHECK (GROSS_WEIGHT_KG>0) ENABLE, 
	 PRIMARY KEY ("LOAD_OPERATION_ID", "BOX_UID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_LOAD_BOX_ORIGIN_C" CHECK (
 (MEASUREMENT_ORIGIN='MANUAL_CONFIRMED'and CASE_BOX_TASK_ID is null and FINAL_SCALE_CAPTURE is null and WAREHOUSE_QC_OPERATION is null
  and TARE_WEIGHT_KG is null and NET_WEIGHT_KG is null and DEVICE_MODE is null and COMPOSITION_SIGNATURE is null and SIGNATURE_VERSION is null and MEASURED_CONTENT_VERSION is null)
 or(MEASUREMENT_ORIGIN='WAREHOUSE_SCALE_QC'and CASE_BOX_TASK_ID is not null and FINAL_SCALE_CAPTURE is not null and WAREHOUSE_QC_OPERATION is not null
  and BOX_UID='CASE:'||to_char(CASE_BOX_TASK_ID,'FM9999999999999999999990')
  and TARE_WEIGHT_KG is not null and NET_WEIGHT_KG is not null and DEVICE_MODE is not null and SIGNATURE_VERSION is not null
  and TARE_WEIGHT_KG>0 and NET_WEIGHT_KG>0 and GROSS_WEIGHT_KG=TARE_WEIGHT_KG+NET_WEIGHT_KG
  and DEVICE_MODE in('TEST','HARDWARE')and COMPOSITION_SIGNATURE is not null and SIGNATURE_VERSION=3 and MEASURED_CONTENT_VERSION is not null
  and MEASURED_CONTENT_VERSION<=BOX_CONTENT_VERSION)) ENABLE, 
	 CONSTRAINT "RRL_LOAD_BOX_COVER_C" CHECK (COVERAGE_COMPLETE in(0,1)) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


