  CREATE TABLE "RABAEV"."RRL_VEHICLE_PROFILE_HIST" 
   (	"VEHICLE_ID" NUMBER NOT NULL ENABLE, 
	"VERSION_NO" NUMBER(19,0) NOT NULL ENABLE, 
	"OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ACTOR" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"VEHICLE_SIZE_CLASS" VARCHAR2(40) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CARGO_LENGTH_MM" NUMBER(7,0) NOT NULL ENABLE, 
	"CARGO_WIDTH_MM" NUMBER(7,0) NOT NULL ENABLE, 
	"CARGO_HEIGHT_MM" NUMBER(7,0) NOT NULL ENABLE, 
