	 CONSTRAINT "RRL_VEH_OUTER_HEIGHT_CK" CHECK (OUTER_HEIGHT_MM is null or (OUTER_HEIGHT_MM between 1 and 1000000 and OUTER_HEIGHT_MM>=CARGO_HEIGHT_MM)) ENABLE, 
	 CONSTRAINT "RRL_VEH_OUTER_LENGTH_CK" CHECK (OUTER_LENGTH_MM is null or (OUTER_LENGTH_MM between 1 and 1000000 and OUTER_LENGTH_MM>=CARGO_LENGTH_MM)) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


