  CREATE TABLE "RABAEV"."RRL_WAREHOUSE_MAP_CAMERA" 
   (	"CAMERA_ID" NUMBER NOT NULL ENABLE, 
	"CANVAS_ID" NUMBER NOT NULL ENABLE, 
	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"CAMERA_CODE" VARCHAR2(80) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CAMERA_NAME" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CAMERA_KIND" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'DRY' NOT NULL ENABLE, 
	"ORIGIN_X_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"ORIGIN_Y_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"ORIGIN_Z_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"WIDTH_M" NUMBER NOT NULL ENABLE, 
	"DEPTH_M" NUMBER NOT NULL ENABLE, 
	"HEIGHT_M" NUMBER NOT NULL ENABLE, 
	"GRID_CELL_WIDTH_M" NUMBER DEFAULT 1.2 NOT NULL ENABLE, 
	"GRID_CELL_DEPTH_M" NUMBER DEFAULT 0.8 NOT NULL ENABLE, 
	"LEVELS" NUMBER DEFAULT 1 NOT NULL ENABLE, 
	"BOUNDARY_JSON" CLOB COLLATE "USING_NLS_COMP", 
	"DEFAULT_PASSAGE_WIDTH_M" NUMBER DEFAULT 3 NOT NULL ENABLE, 
	"DEFAULT_AISLE_SPACING_M" NUMBER, 
	"STATUS" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'DRAFT' NOT NULL ENABLE, 
	"ACTIVE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CREATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"UPDATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"UPDATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_WH_MAP_CAMERA_CHK_KIND" CHECK (CAMERA_KIND in ('DRY', 'COLD', 'FREEZER', 'DOCK', 'SERVICE', 'MIXED')) ENABLE, 
	 CONSTRAINT "RRL_WH_MAP_CAMERA_CHK_STATUS" CHECK (STATUS in ('DRAFT', 'ACTIVE', 'ARCHIVED')) ENABLE, 
	 CONSTRAINT "RRL_WH_MAP_CAMERA_CHK_SIZE" CHECK (
        WIDTH_M > 0 and DEPTH_M > 0 and HEIGHT_M > 0 and
        GRID_CELL_WIDTH_M > 0 and GRID_CELL_DEPTH_M > 0 and
        LEVELS > 0 and DEFAULT_PASSAGE_WIDTH_M > 0 and
        (DEFAULT_AISLE_SPACING_M is null or DEFAULT_AISLE_SPACING_M > 0)
      ) ENABLE, 
	 CONSTRAINT "RRL_WH_MAP_CAMERA_CHK_ACTIVE" CHECK (ACTIVE in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_WH_MAP_CAMERA_PK" PRIMARY KEY ("CAMERA_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_WH_MAP_CAMERA_CK_WARE_POS" CHECK (WARE_ID > 0) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_WAREHOUSE_MAP_CAMERA_LINK" 
   (	"CAMERA_LINK_ID" NUMBER NOT NULL ENABLE, 
	"CANVAS_ID" NUMBER NOT NULL ENABLE, 
	"FROM_CAMERA_ID" NUMBER NOT NULL ENABLE, 
	"TO_CAMERA_ID" NUMBER NOT NULL ENABLE, 
	"LINK_CODE" VARCHAR2(80) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"LINK_KIND" VARCHAR2(40) COLLATE "USING_NLS_COMP" DEFAULT 'DOOR' NOT NULL ENABLE, 
	"FROM_POINT_X_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"FROM_POINT_Y_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"FROM_POINT_Z_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"TO_POINT_X_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"TO_POINT_Y_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"TO_POINT_Z_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"DISTANCE_M" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"TRAVEL_TIME_SEC" NUMBER, 
	"DIRECTION_CODE" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'BOTH' NOT NULL ENABLE, 
	"ALLOWED_RESOURCE_MASK" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"ACTIVE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CREATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	"UPDATED_AT" DATE DEFAULT sysdate NOT NULL ENABLE, 
	"UPDATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_WH_MAP_LINK_CHK_KIND" CHECK (LINK_KIND in ('DOOR', 'CORRIDOR', 'GATE', 'LIFT', 'STAGING_PASSAGE', 'SERVICE')) ENABLE, 
	 CONSTRAINT "RRL_WH_MAP_LINK_CHK_DIR" CHECK (DIRECTION_CODE in ('BOTH', 'FROM_TO', 'TO_FROM')) ENABLE, 
	 CONSTRAINT "RRL_WH_MAP_LINK_CHK_SIZE" CHECK (
        FROM_CAMERA_ID <> TO_CAMERA_ID and
        DISTANCE_M >= 0 and
        (TRAVEL_TIME_SEC is null or TRAVEL_TIME_SEC >= 0)
      ) ENABLE, 
	 CONSTRAINT "RRL_WH_MAP_LINK_CHK_ACTIVE" CHECK (ACTIVE in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_WH_MAP_CAMERA_LINK_PK" PRIMARY KEY ("CAMERA_LINK_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


