	 CONSTRAINT "RRL_WH_MAP_CANVAS_CHK_ACTIVE" CHECK (ACTIVE in (0, 1)) ENABLE, 
	 CONSTRAINT "RRL_WH_MAP_CANVAS_PK" PRIMARY KEY ("CANVAS_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_WH_MAP_CANVAS_CK_WARE_POS" CHECK (WARE_ID > 0) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


