  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_WAREHOUSE_TASK" 
   (	"TASK_ID" NUMBER NOT NULL ENABLE, 
