	"PROD_BATCH_ID" NUMBER, 
	"RAW_ARTICUL" VARCHAR2(40) COLLATE "USING_NLS_COMP", 
	"TARGET_ARTICUL" VARCHAR2(40) COLLATE "USING_NLS_COMP", 
	"UID_PALLET" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"SSCC" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"FROM_WARE_ID" NUMBER, 
	"FROM_CELL" VARCHAR2(80) COLLATE "USING_NLS_COMP", 
	"TO_WARE_ID" NUMBER, 
	"TO_CELL" VARCHAR2(80) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"QTY" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"UNIT_CODE" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"PRIORITY" NUMBER DEFAULT 100 NOT NULL ENABLE, 
	"STATUS" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'PLANNED' NOT NULL ENABLE, 
	"ASSIGNED_TO" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"CREATED_AT" TIMESTAMP (6) DEFAULT systimestamp NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"STARTED_AT" TIMESTAMP (6), 
	"FINISHED_AT" TIMESTAMP (6), 
	"CANCELLED_AT" TIMESTAMP (6), 
	"CANCELLED_BY" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"LAST_ERROR" VARCHAR2(2000) COLLATE "USING_NLS_COMP", 
	"QTY_MODE" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'BOX' NOT NULL ENABLE, 
	"FACT_QTY" NUMBER, 
	"PARENT_TASK_ID" NUMBER, 
	"RESOURCE_ID" NUMBER, 
	"RESOURCE_SESSION_ID" NUMBER, 
	"EQUIPMENT_ID" NUMBER, 
	"PLANNED_START_AT" TIMESTAMP (6), 
	"PLANNED_FINISH_AT" TIMESTAMP (6), 
	"DISPATCH_PRIORITY" NUMBER, 
	"FROM_CELL_SLOT_ID" NUMBER, 
	"TO_CELL_SLOT_ID" NUMBER, 
	"COMPLETION_HASH" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"COMPLETION_JSON" CLOB COLLATE "USING_NLS_COMP", 
	"TARGET_UID_PALLET" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"STARTED_AT_INSTANT" TIMESTAMP (6) WITH TIME ZONE, 
	"STARTED_SHIFT_TIME_ZONE" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"HU_CONTENT_VERSION" NUMBER, 
	"HU_MEASUREMENTS_JSON" CLOB COLLATE "USING_NLS_COMP", 
	"FINISHED_AT_INSTANT" TIMESTAMP (6) WITH TIME ZONE, 
	 CONSTRAINT "RRL_WAREHOUSE_TASK_CHK3" CHECK (STATUS in ('PLANNED', 'ASSIGNED', 'IN_PROGRESS', 'DONE', 'CANCELLED', 'ERROR')) ENABLE, 
	 CONSTRAINT "RRL_WAREHOUSE_TASK_CHK4" CHECK (QTY >= 0) ENABLE, 
	 CONSTRAINT "RRL_WAREHOUSE_TASK_PK" PRIMARY KEY ("TASK_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_WAREHOUSE_TASK_CHK1" CHECK (TASK_TYPE in ('RAW_TO_PRODUCTION','FG_TO_STORAGE','REPLENISHMENT','PICKING_MOVE','OTHER','PUTAWAY')) ENABLE, 
	 CONSTRAINT "RRL_WAREHOUSE_TASK_CHK2" CHECK (TASK_SOURCE in ('MES_RAW_SUPPLY','MES_COMPLETION','PICKING','WAVE','MANUAL','SAP_RECEIPT')) ENABLE, 
	 CONSTRAINT "RRL_WH_TASK_COMPLETION_JSON" CHECK (COMPLETION_JSON is json) ENABLE, 
	 CHECK (HU_MEASUREMENTS_JSON is json) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


