   (	"CAPTURE_KEY" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"STOCK_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TARE_CAPTURE_KEY" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CASE_PICK_TASK_ID" NUMBER NOT NULL ENABLE, 
	"CASE_CONTENT_VERSION" NUMBER NOT NULL ENABLE, 
	"COMPOSITION_SIGNATURE" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ACTOR" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"USED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	"SIGNATURE_VERSION" NUMBER(2,0) DEFAULT 2 NOT NULL ENABLE, 
	 PRIMARY KEY ("CAPTURE_KEY")
  USING INDEX  ENABLE, 
	 UNIQUE ("STOCK_OPERATION_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_WH_FINAL_USE_VERSION_C" CHECK (SIGNATURE_VERSION in(2,3)) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_WH_SCALE_CAPTURE" 
   (	"CAPTURE_KEY" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"DEVICE_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CAPTURE_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"POST_CELL" VARCHAR2(60) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CASE_PICK_TASK_ID" NUMBER NOT NULL ENABLE, 
	"CASE_PICK_LINE_ID" NUMBER, 
	"CASE_CONTENT_VERSION" NUMBER NOT NULL ENABLE, 
	"ARTICLE" VARCHAR2(160) COLLATE "USING_NLS_COMP", 
	"SOURCE_CELL" VARCHAR2(60) COLLATE "USING_NLS_COMP", 
	"CARRIER_IDENTIFIER" VARCHAR2(150) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SCANNED_PRODUCT" VARCHAR2(512) COLLATE "USING_NLS_COMP", 
	"DEVICE_POLICY_VERSION" NUMBER(10,0) NOT NULL ENABLE, 
	"DEVICE_MODE" VARCHAR2(10) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"MEASUREMENT_BASIS" VARCHAR2(5) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"WEIGHT_KG" NUMBER(27,9) NOT NULL ENABLE, 
	"RESOLUTION_KG" NUMBER(27,9) NOT NULL ENABLE, 
	"CALIBRATION_REF" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"MEASURED_AT" TIMESTAMP (6) WITH TIME ZONE NOT NULL ENABLE, 
	"RECEIVED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	"RECORDED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SOURCE_SHA256" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SOURCE_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RESULT_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CAPTURE_PURPOSE" VARCHAR2(12) COLLATE "USING_NLS_COMP" DEFAULT 'PICK' NOT NULL ENABLE, 
	"TARE_CAPTURE_KEY" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"PALLET_TYPE_ID" NUMBER, 
	"TYPE_VERSION" NUMBER, 
	"COMPOSITION_SIGNATURE" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	 CHECK (WEIGHT_KG>0) ENABLE, 
	 CHECK (SOURCE_JSON is json) ENABLE, 
	 CHECK (RESULT_JSON is json) ENABLE, 
	 PRIMARY KEY ("CAPTURE_KEY")
  USING INDEX  ENABLE, 
	 UNIQUE ("DEVICE_ID", "CAPTURE_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_WH_SCALE_PURPOSE_C" CHECK (CAPTURE_PURPOSE in('PICK','EMPTY_TARE','FINAL_GROSS')) ENABLE, 
	 CONSTRAINT "RRL_WH_SCALE_SOURCE_C" CHECK (
 (CAPTURE_PURPOSE='PICK' and CASE_PICK_LINE_ID is not null and ARTICLE is not null and SOURCE_CELL is not null and SCANNED_PRODUCT is not null and TARE_CAPTURE_KEY is null)
 or(CAPTURE_PURPOSE='EMPTY_TARE' and CASE_PICK_LINE_ID is null and ARTICLE is null and SOURCE_CELL is null and SCANNED_PRODUCT is null
  and PALLET_TYPE_ID is not null and TYPE_VERSION is not null and TARE_CAPTURE_KEY is null and COMPOSITION_SIGNATURE is null)
 or(CAPTURE_PURPOSE='FINAL_GROSS' and CASE_PICK_LINE_ID is null and ARTICLE is null and SOURCE_CELL is null and SCANNED_PRODUCT is null
  and PALLET_TYPE_ID is not null and TYPE_VERSION is not null and TARE_CAPTURE_KEY is not null and COMPOSITION_SIGNATURE is not null)) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_WH_SCALE_DEVICE" 
   (	"DEVICE_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"POST_CELL" VARCHAR2(60) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"SENDER_ID" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"POLICY_VERSION" NUMBER(10,0) DEFAULT 1 NOT NULL ENABLE, 
	"ACTIVE_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE, 
	"DEVICE_MODE" VARCHAR2(10) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"MEASUREMENT_BASIS" VARCHAR2(5) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CAPACITY_KG" NUMBER(27,9) NOT NULL ENABLE, 
	"RESOLUTION_KG" NUMBER(27,9) NOT NULL ENABLE, 
	"CALIBRATION_REF" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CALIBRATED_UNTIL" TIMESTAMP (6) WITH TIME ZONE NOT NULL ENABLE, 
	"CHANGED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CHANGED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	 CHECK (POLICY_VERSION>=1) ENABLE, 
	 CHECK (ACTIVE_FLAG in(0,1)) ENABLE, 
	 CHECK (DEVICE_MODE in('TEST','HARDWARE')) ENABLE, 
	 CHECK (MEASUREMENT_BASIS in('NET','GROSS')) ENABLE, 
	 CHECK (CAPACITY_KG>0) ENABLE, 
	 CHECK (RESOLUTION_KG>0) ENABLE, 
	 PRIMARY KEY ("DEVICE_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


