	 PRIMARY KEY ("CAPTURE_KEY")
  USING INDEX  ENABLE, 
	 UNIQUE ("STOCK_OPERATION_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_WMS_HU_LINK" 
   (	"HU_LINK_ID" NUMBER, 
	"PARENT_UID" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CHILD_PALLET_UID" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"CHILD_CASE_TASK_ID" NUMBER, 
	"ACTIVE_FLAG" NUMBER DEFAULT 1 NOT NULL ENABLE, 
	"LINK_VERSION" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"LINKED_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"LINKED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	"LINKED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"UNLINKED_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"UNLINKED_AT" TIMESTAMP (6) WITH TIME ZONE, 
	"UNLINKED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_HU_LINK_CK" CHECK (ACTIVE_FLAG in(0,1) and LINK_VERSION>=0 and LINK_VERSION=trunc(LINK_VERSION)
   and ((CHILD_PALLET_UID is not null and CHILD_CASE_TASK_ID is null and CHILD_PALLET_UID!=PARENT_UID)
    or (CHILD_PALLET_UID is null and CHILD_CASE_TASK_ID is not null))) ENABLE, 
	 PRIMARY KEY ("HU_LINK_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_WMS_RECEIPT_AGG" 
   (	"SYSTEM_CODE" VARCHAR2(40) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CODE_HASH" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"UID_PALLET" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PROFILE_CODE" VARCHAR2(80) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"AGG_LEVEL" VARCHAR2(10) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RAW_CODE" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	 CONSTRAINT "RRL_WMS_REC_AGG_LVL" CHECK (AGG_LEVEL in('BOX','PALLET')) ENABLE, 
	 CONSTRAINT "RRL_WMS_REC_AGG_PK" PRIMARY KEY ("SYSTEM_CODE", "CODE_HASH")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_WMS_RECEIPT_CODE" 
   (	"SYSTEM_CODE" VARCHAR2(40) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CODE_HASH" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"UID_PALLET" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"UNIT_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RAW_CODE" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PROFILES_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CANONICAL_CODE" VARCHAR2(4000) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	 CONSTRAINT "RRL_WMS_REC_CODE_JSON" CHECK (PROFILES_JSON is json) ENABLE, 
	 CONSTRAINT "RRL_WMS_REC_CODE_PK" PRIMARY KEY ("SYSTEM_CODE", "CODE_HASH")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_WMS_RECEIPT_UNIT" 
   (	"UID_PALLET" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"UNIT_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"POLICY_VERSION" NUMBER NOT NULL ENABLE, 
	"BASE_QTY" NUMBER DEFAULT 1 NOT NULL ENABLE, 
	"PHYSICAL_UNIT_KEY" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"CURRENT_UID" VARCHAR2(200) COLLATE "USING_NLS_COMP", 
	"CURRENT_CELL" VARCHAR2(60) COLLATE "USING_NLS_COMP", 
	"BASE_UOM" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"STOCK_STATUS" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"UNIT_VERSION" NUMBER DEFAULT 0 NOT NULL ENABLE, 
	"HARD_RESERVATION_ID" NUMBER, 
	"GROSS_WEIGHT_KG" NUMBER(27,9), 
	"BOX_VOLUME_M3" NUMBER(27,9), 
	"MEASUREMENT_REFERENCE" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP", 
	"WEIGHT_LABEL_SCAN" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "RRL_WMS_REC_UNIT_PK" PRIMARY KEY ("UID_PALLET", "UNIT_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "RRL_WMS_REC_UNIT_QTY_CK" CHECK (BASE_QTY>0) ENABLE, 
	 CONSTRAINT "RRL_UNIT_BOX_MEASURES_CK" CHECK ((GROSS_WEIGHT_KG is null or (GROSS_WEIGHT_KG>0 and (BASE_UOM!='KG' or GROSS_WEIGHT_KG>=BASE_QTY)))
  and (BOX_VOLUME_M3 is null or BOX_VOLUME_M3>0)
  and ((GROSS_WEIGHT_KG is null and BOX_VOLUME_M3 is null)or MEASUREMENT_REFERENCE is not null)) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;
  CREATE UNIQUE INDEX "RABAEV"."RRL_RECEIPT_UNIT_PHYSICAL_UK" ON "RABAEV"."RRL_WMS_RECEIPT_UNIT" ("PHYSICAL_UNIT_KEY") 
  ;
ALTER TABLE "RABAEV"."RRL_WMS_RECEIPT_UNIT" ADD CONSTRAINT "RRL_RECEIPT_UNIT_KEY_UK" UNIQUE ("PHYSICAL_UNIT_KEY")
  USING INDEX "RABAEV"."RRL_RECEIPT_UNIT_PHYSICAL_UK"  ENABLE;


  CREATE TABLE "RABAEV"."RRL_WORKLOAD_ATTENDANCE" 
   (	"PLAN_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"SITE_CODE" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RESOURCE_ID" NUMBER NOT NULL ENABLE, 
	"PERSON_ID" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"START_AT" TIMESTAMP (6) WITH TIME ZONE NOT NULL ENABLE, 
	"FINISH_AT" TIMESTAMP (6) WITH TIME ZONE NOT NULL ENABLE, 
	"TASK_TYPE" VARCHAR2(40) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REASON" NVARCHAR2(500) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	 CHECK (TASK_TYPE='CASE_PICK') ENABLE, 
	 CHECK (FINISH_AT>START_AT) ENABLE, 
	 PRIMARY KEY ("PLAN_OPERATION_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_WORKLOAD_ATTEND_CANCEL" 
   (	"PLAN_OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
