	"REASON" NVARCHAR2(500) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	 PRIMARY KEY ("PLAN_OPERATION_ID")
  USING INDEX  ENABLE, 
	 UNIQUE ("CANCEL_OPERATION_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_WORKLOAD_NORM" 
   (	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"SITE_CODE" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ARTICLE" VARCHAR2(160) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BASE_UOM" VARCHAR2(20) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"VERSION_NO" NUMBER(19,0) NOT NULL ENABLE, 
	"BASE_PER_HOUR" NUMBER(38,9) NOT NULL ENABLE, 
	"ACTIVE" NUMBER(1,0) NOT NULL ENABLE, 
	"REASON" NVARCHAR2(500) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CREATED_BY" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CREATED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
	 CHECK (VERSION_NO>=1) ENABLE, 
	 CHECK (BASE_PER_HOUR>0) ENABLE, 
	 CHECK (ACTIVE in(0,1)) ENABLE, 
	 PRIMARY KEY ("WARE_ID", "SITE_CODE", "ARTICLE", "BASE_UOM", "VERSION_NO")
  USING INDEX  ENABLE, 
	 UNIQUE ("OPERATION_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "RABAEV"."RRL_WORKLOAD_OPERATION" 
   (	"OPERATION_ID" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"WARE_ID" NUMBER NOT NULL ENABLE, 
	"ACTION_KIND" VARCHAR2(20) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ACTOR" NVARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REQUEST_HASH" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RESULT_JSON" CLOB COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CREATED_AT" TIMESTAMP (6) WITH TIME ZONE DEFAULT systimestamp NOT NULL ENABLE, 
